451: 
452:         thisServ->next = gServiceList;
453:         gServiceList = thisServ;
454: 
455:         if (gMDNSPlatformPosixVerboseLevel > 0) {
456:             fprintf(stderr,
457:                     "%s: Registered service %d, name \"%s\", type \"%s\", domain \"%s\",  port %ld\n",
458:                     gProgramName,
459:                     thisServ->serviceID,
460:                     richTextName,
461:                     serviceType,
462:                     serviceDomain,
463:                     portNumber);
464:         }
465:     } else {
466:         if (thisServ != NULL) {
467:             free(thisServ);
468:         }
469:     }
470:     return status;
