614: static mStatus RegisterOurServices(void)
615: {
616:     mStatus status;
617: 
618:     status = mStatus_NoError;
619:     if (gServiceName[0] != 0) {
620:         status = RegisterOneService(gServiceName,
621:                                     gServiceType,
622:                                     gServiceDomain,
623:                                     gServiceText, gServiceTextLen,
624:                                     gPortNumber);
625:     }
626:     if (status == mStatus_NoError && gServiceFile[0] != 0) {
627:         status = RegisterServicesInFile(gServiceFile);
628:     }
629:     return status;
